{"file_path":"src/parse.js","content":"/**
 * Input parsing: splitting stdin into lines and then into the three
 * documents separated by lines that are exactly `%%%`.
 */

export function splitLines(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function splitParts(lines) {
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  return parts
}
"}

