{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence between a base document and a side document,
 * with the tie-breaking rule described in the specification, reduced to a
 * list of changes: runs of base lines replaced by runs of side lines.
 */

export function computeChanges(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:]
  const stride = m + 1
  const dp = new Int32Array((n + 1) * stride)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      const idx = i * stride + j
      if (base[i] === side[j]) {
        dp[idx] = dp[(i + 1) * stride + (j + 1)] + 1
      } else {
        const down = dp[(i + 1) * stride + j]
        const right = dp[i * stride + (j + 1)]
        dp[idx] = down > right ? down : right
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const down = dp[(i + 1) * stride + j]
      const right = dp[i * stride + (j + 1)]
      if (down >= right) {
        i++
      } else {
        j++
      }
    }
  }

  const changes = []
  let prevB = -1
  let prevS = -1
  for (let k = 0; k <= matches.length; k++) {
    const curB = k < matches.length ? matches[k][0] : n
    const curS = k < matches.length ? matches[k][1] : m
    const baseStart = prevB + 1
    const baseEnd = curB
    const sideStart = prevS + 1
    const sideEnd = curS
    if (baseEnd > baseStart || sideEnd > sideStart) {
      changes.push({ baseStart, baseEnd, sideStart, sideEnd })
    }
    prevB = curB
    prevS = curS
  }

  return changes
}
"}

