{"file_path":"src/merge.js","content":"/**
 * Combines the changes found on each side into regions, and resolves each
 * region against the base, following the specification's rules.
 */

import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let k = 0; k < a.length; k++) {
    if (a[k] !== b[k]) return false
  }
  return true
}

// Builds the lines a side resolves to for a region, given the base document,
// the side's document, and the side's own changes that touch the region
// (sorted by base start, already known to lie within [regionStart, regionEnd)).
function sideLinesForRegion(base, side, changes, regionStart, regionEnd) {
  const out = []
  let cursor = regionStart
  for (const c of changes) {
    if (c.baseStart > cursor) {
      for (let k = cursor; k < c.baseStart; k++) out.push(base[k])
    }
    for (let k = c.sideStart; k < c.sideEnd; k++) out.push(side[k])
    cursor = c.baseEnd
  }
  if (cursor < regionEnd) {
    for (let k = cursor; k < regionEnd; k++) out.push(base[k])
  }
  return out
}

export function buildPlan(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))

  const all = mineChanges.concat(theirsChanges)
  all.sort((a, b) => a.baseStart - b.baseStart)

  const segments = []
  let cursor = 0
  let idx = 0
  while (idx < all.length) {
    const first = all[idx]
    if (first.baseStart > cursor) {
      segments.push({ kind: 'stable', lines: base.slice(cursor, first.baseStart) })
    }
    let regionStart = first.baseStart
    let regionEnd = first.baseEnd
    const regionChanges = [first]
    idx++
    while (idx < all.length && all[idx].baseStart <= regionEnd) {
      regionChanges.push(all[idx])
      if (all[idx].baseEnd > regionEnd) regionEnd = all[idx].baseEnd
      idx++
    }

    const mineOwn = regionChanges.filter(c => c.side === 'mine')
    const theirsOwn = regionChanges.filter(c => c.side === 'theirs')

    const mineLines = sideLinesForRegion(base, mine, mineOwn, regionStart, regionEnd)
    const theirsLines = sideLinesForRegion(base, theirs, theirsOwn, regionStart, regionEnd)
    const baseLines = base.slice(regionStart, regionEnd)

    let resolution
    let lines
    if (arraysEqual(mineLines, theirsLines)) {
      resolution = 'both'
      lines = mineLines
    } else if (arraysEqual(mineLines, baseLines)) {
      resolution = 'theirs'
      lines = theirsLines
    } else if (arraysEqual(theirsLines, baseLines)) {
      resolution = 'mine'
      lines = mineLines
    } else {
      resolution = 'conflict'
      lines = null
    }

    segments.push({ kind: 'region', resolution, lines, mineLines, baseLines, theirsLines })
    cursor = regionEnd
  }

  if (cursor < base.length) {
    segments.push({ kind: 'stable', lines: base.slice(cursor, base.length) })
  }

  return segments
}
